import { Card, IconButton } from "march/ui"
import { refresh } from "march/icons"

// günün sözü: başlıktaki düğme sıradaki söze geçer, alt bilgi kaçıncı söz olduğunu yazar
const QUOTES = [
  { text: "Basit olan, karmaşığın en zor hâlidir.", who: "Leonardo da Vinci" },
  { text: "Önce çalıştır, sonra doğru yap, sonra hızlandır.", who: "Kent Beck" },
  { text: "Sabır acıdır, meyvesi tatlıdır.", who: "Atasözü" },
]

export function FlipQuote() {
  let $i = 0
  const q = () => QUOTES[$i % QUOTES.length]
  return <Card title="Günün sözü" subtitle={() => q().who}
    actions={<IconButton icon={refresh} label="Sıradaki söz" on:click={() => $i++} />}
    footer={<span sx={{ text: "xs", color: "muted" }}>{() => `${($i % QUOTES.length) + 1} / ${QUOTES.length}`}</span>}>
    <p sx={{ text: "lg" }}>{() => `“${q().text}”`}</p>
  </Card>
}

import { Card, Button, Toggle } from "march/ui"
import { edit, trash } from "march/icons"

// Card'ın bütün özellikleri bir arada: title, subtitle, actions (düğüm dizisi), footer, as, flush, plain (canlı),
// class, gövde (children) ve kendi HTML öznitelikleri (id, aria-label…)
export function CardLab() {
  let $plain = false
  let $removed = 0
  return <div sx={{ flex: "col", gap: 3 }}>
    <Toggle label="Çerçevesiz" bind:value={$plain} />
    <Card class="lab-card" id="lab-card" as="article" title="Başlık" subtitle="Alt başlık" plain={() => $plain}
      actions={[<Button size="sm" icon={edit}>Düzenle</Button>, <Button size="sm" variant="danger" icon={trash} on:click={() => $removed++}>Sil</Button>]}
      footer={<span>{() => `Silme sayısı: ${$removed}`}</span>}>
      Kartın gövdesi: istediğiniz her şey.
    </Card>
    <Card flush title="Kenar boşluksuz (flush)" aria-label="Liste kartı">
      <ul sx={{ m: 0 }}><li>Birinci satır</li><li>İkinci satır</li></ul>
    </Card>
    <Card m:theme="night" as="div">Başlıksız, koyu zemin: yalnız gövde.</Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { CardLab } from "./CardLab.tsx"

// CardLab'in testleri: kaydedince Testler sekmesinde çalışır
test("as kök etiketini, class ve id kartı belirler", () => {
  const s = renderTest(() => <CardLab />)
  const card = s.get(".lab-card")!
  expect(card.tagName).toBe("ARTICLE")
  expect(card.id).toBe("lab-card")
  expect(card.querySelector(".m-card-title")!.textContent).toBe("Başlık")
})

test("eylemdeki Sil düğmesi alt bilgiyi günceller", async () => {
  const s = renderTest(() => <CardLab />)
  await s.click("Sil")
  expect(s.get(".lab-card footer")!.textContent).toBe("Silme sayısı: 1")
})

test("plain anahtarla açılır, flush sınıfı yazılır", async () => {
  const s = renderTest(() => <CardLab />)
  expect(s.get(".lab-card")!.classList.contains("m-card-plain")).toBe(false)
  await s.click("Çerçevesiz")
  expect(s.get(".lab-card")!.classList.contains("m-card-plain")).toBe(true)
  expect(s.find("Liste kartı")!.classList.contains("m-card-flush")).toBe(true)
})
